"""Seven original Hearthseed Slinger action guides; preserve reviewed idle18-25."""
import json
import produce as p
UID=p.SOURCE_DIR.name
B=p.ROOT/'art/animation/source/poses'/UID
IDENTITY=('Original HEARTHSEED SLINGER from supplied original paintings, fixed three-quarter tactical camera facing SCREEN RIGHT. One human forest woman with exactly TWO arms, TWO hands and TWO human legs. Brown curly tied hair with small yellow flowers, green scarf, cream sleeves, bark-brown leather and green leaf armor skirt, dark green trousers, vine-wrapped brown boots, belt amber seed pouches and metal hooks. ONE wooden Y-fork sling staff with two fixed amber ornaments beside the fork, TWO attached long green straps and ONE brown leather sling pouch. ONE original small round wicker buckler with amber boss. Anatomical RIGHT staff hand at SCREEN LEFT in ready grips the same wooden staff; anatomical LEFT arm at SCREEN RIGHT in ready carries the same buckler. Keep the hand jobs separate, full wooden butt, fork, straps and pouch attached; never duplicate a hand, shield, staff, fork or pouch. Original painted fantasy strategy sprite materials, proportions, camera and silhouette. ')
PLATE=(' Plain uniform neutral gray RGB128,128,128 backdrop like every supplied guide, with clean natural brown/green/cream subject edges and no colored rim. No scenery, floor, cast shadow, cuts, zoom, camera turn or root travel. Anatomical root x480 and ground reference y576. Full equipment, hair, boot tips and corpse remain inside generous margins. Game owns projectile flight/effects: no detached rendered shots, trails, rings, particles, beams or magic. ')

def reference(index):
 f=dict(json.loads((B/'packing.json').read_bytes())['frames'][index]);f['source']=(B/f['source']).relative_to(p.ROOT).as_posix();f['alpha_noise_cutoff']=8
 if index==17:
  f['anchor']=[f['anchor'][0],1209]
  f['registration_note']='Original corpse near forearm/body contact at source y1209; foreground wooden staff and sling extend below it. Whole-guide registration once, not per-frame stabilization.'
 return f

def support():
 return dict(source=(p.SOURCE_DIR/'support_v1.png').relative_to(p.ROOT).as_posix(),rects=[[0,0,1087,1446]],anchor=[665,1360],scale=.16,alpha_noise_cutoff=8)

def recipe(clip,refs,guides,last,action,seed):
 out=p.SOURCE_DIR/(clip+'_h3_v1');out.mkdir(exist_ok=True)
 assert not (out/'sampling_submission.json').exists(), 'Submitted source is immutable; prepare a separate corrected take.'
 identity=IDENTITY
 if clip=='death':identity=identity.replace('grips the same wooden staff','initially grips the same wooden staff and naturally releases it onto the foreground ground during collapse')
 c=dict(unit_id=UID,clip=clip,canvas=[960,704],anchor=[480,576],scale=.5,key_rgb=[128,128,128],seed=seed,references=refs,guides=guides,last=last,prompt=(identity+action+PLATE).strip(),tiled_decode=dict(tile_size=512,overlap=64,temporal_size=16,temporal_overlap=4))
 p.write(out/'config.json',c);p.prepare(out,c);p.verify(out,c);print('Prepared',clip,flush=True)

if __name__=='__main__':
 assert not any(p.SOURCE_DIR.glob('*/sampling_submission.json')), 'Initial preparation cannot overwrite submitted originals or corrected delivery choices.'
 ready=reference(18)
 recipe('move',[ready,reference(5),reference(3)],[[34,1],[78,2]],0,'One reciprocal walking cycle IN PLACE. The foreground knee on SCREEN RIGHT rises and its boot passes the planted opposite leg as in guide1, then extends and plants. The rear leg at SCREEN LEFT then bends and its heel lifts and passes as in guide2 while the foreground leg supports the body. Both human hips, knees and ankles articulate through two alternating steps, passing, extension and loading; no one-leg shuffle. Same staff stays upright in RIGHT hand, same shield remains on LEFT arm, sling pouch swings from its attached straps as cloth follows. Return smoothly to exact initial ready. ',2026109301)
 recipe('attack',[ready,reference(6),reference(7)],[[32,1],[62,2]],0,'One original physical wicker-SHIELD BASH. Staff stays upright in RIGHT hand on SCREEN LEFT; no staff swing or shot. LEFT buckler arm draws shield close, elbow bends and torso lowers slightly in original windup, then LEFT elbow extends to drive ONE shield boss forward toward SCREEN RIGHT through original contact guide. Two boots brace and transfer weight; retract the same left arm and shield smoothly to exact initial ready. Preserve shield size and buckler grip throughout. ',2026109302)
 recipe('ranged',[ready,reference(10),reference(11),reference(12)],[[32,1],[62,2],[94,3]],0,'One physical sling-staff shot. Draw the ONE loaded sling staff backward and upward in RIGHT hand, pouch and amber seed trailing on attached green straps. Swing the same staff forward toward SCREEN RIGHT, elbow extends and hips transfer weight through original release guide. The pouch opens EMPTY and green straps remain connected to the fork; retain two fixed amber ornaments at fork and belt seeds. No separate flying projectile is drawn. Follow through with empty pouch, draw staff back upright, LEFT shield hand briefly takes one belt seed for original reload while shield stays strapped to forearm, reseat seed in SAME pouch, and recover exact ready. No bowstring, crossbow, magical staff or second sling. ',2026109303)
 recipe('hit',[ready,reference(13)],[[48,1]],0,'One continuous impact recoil: chest and head lean back briefly, two knees flex and planted boots brace; RIGHT hand keeps same staff grip and LEFT arm keeps shield. Recover upright to exact ready without falling or losing the sling assembly. ',2026109304)
 recipe('defend',[ready,reference(8),reference(9)],[[62,1]],2,'One dedicated defensive brace. Both knees bend into original low wide guard, LEFT elbow brings wicker shield in front of chest and head bows behind it; RIGHT hand retains upright staff, hanging sling remains intact. Continue smoothly to original held guard. Hold defensive endpoint for final second; no return to idle or firing. ',2026109305)
 recipe('cast',[ready,support()],[[54,1]],0,'One physical non-magical allied acknowledgement. RIGHT hand holds original upright staff continuously. LEFT buckler arm bends and brings SAME shield inward and upward to sternum with a respectful head nod through supplied chest-level gesture. Both boots stay planted and original sling pouch hangs naturally. Pause briefly at acknowledgement then lower buckler and head, returning smoothly to exact original ready. No spellcasting, floating seeds or effects. ',2026109306)
 recipe('death',[ready,reference(14),reference(15),reference(17)],[[32,1],[66,2]],3,'One continuous grounded collapse. Two knees buckle into original kneeling guide, torso loses support and tips forward. RIGHT hand releases ONE staff which falls intact onto foreground ground, LEFT shield arm folds under chest as original body rolls onto side. Keep both arms and legs attached, same fork/straps/pouch and single buckler. Settle near forearm/body contact at original y576 ground reference; foreground staff may lie below body contact in perspective. Hold exact supplied grounded corpse for final second. No recovery, shrinking, disappearing, extra limbs or upright loose pole. ',2026109307)
 p.write(p.SOURCE_DIR/'delivery.json',dict(takes=[c+'_h3_v1' for c in ['move','attack','ranged','hit','defend','cast','death']],preserved_accepted_clips=['idle'],visual_review=dict(status='pending',notes='All26 original poses inspected; idle18-25 has visible staff-hand and buckler elbow articulation with coherent ready return at native scale on light/dark grounds. Preserve original8x240ms idle/map exactly. Seven dedicated H3 actions require full personal source/native/reflected/action/map acceptance.')))
 p.write(p.SOURCE_DIR/'runtime_registration.json',dict(unit_id=UID,reference_height=256,output_scale=.5,canvas=[960,704],ground_anchor=[480,576],ready_guide=ready,corpse_guide=reference(17),reason='One original anatomical scale per painting, fixed .5 extraction scale. Extra lower canvas margin preserves foreground fallen staff; corpse contact corrected once from original near-forearm point.'))
